SourceCode.Declaration:
/// <summary>
/// Table class for NVOrderTemplate - Order template configuration records.
/// Templates define report mappings and serve as a bridge between order headers and order types.
/// </summary>
/// <remarks>
/// Relationships:
/// - Links to NVOrderTypeTable for order type classification
/// - Referenced by NVOrderHeader via TemplateId
/// - Provides report configuration (ReportName, ReportDesign)
///
/// Purpose: Allows flexible report assignment per order type without hardcoding report names.
/// </remarks>
public class NVOrderTemplate extends common
{
}

Method.Source:
/// <summary>
/// Determines if concurrent deletes should throw an exception.
/// </summary>
/// <returns>True if exception should be thrown on concurrent delete, otherwise false</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    boolean ret;

    ret = super();

    return ret;
}

/// <summary>
/// Retrieves the related NVOrderTypeTable record.
/// </summary>
/// <returns>NVOrderTypeTable record linked to this template</returns>
public NVOrderTypeTable orderType()
{
    return NVOrderTypeTable::find(this.OrderTypeRecId);
}

/// <summary>
/// Retrieves the NVOrderTypeGroup record through the order type relationship.
/// Navigates: Template → OrderType → Group
/// </summary>
/// <returns>NVOrderTypeGroup record, or null if order type not found</returns>
public NVOrderTypeGroup group()
{
    NVOrderTypeTable orderTypeTable = this.orderType();
    return orderTypeTable.RecId ? orderTypeTable.group() : null;
}

/// <summary>
/// Finds an NVOrderTemplate record by RecId.
/// </summary>
/// <param name="_recId">RecId of the template to find</param>
/// <param name="_forUpdate">If true, selects the record for update</param>
/// <returns>NVOrderTemplate record, or empty record if not found</returns>
public static NVOrderTemplate find(RecId _recId, boolean _forUpdate = false)
{
    NVOrderTemplate template;

    if (!_recId)
    {
        return template;
    }

    if (_forUpdate)
    {
        template.selectForUpdate(_forUpdate);
    }

    select firstonly template
        where template.RecId == _recId;

    return template;
}

/// <summary>
/// Checks if a template record exists by RecId.
/// Lightweight existence check without retrieving the full record.
/// </summary>
/// <param name="_recId">RecId of the template to check</param>
/// <returns>True if the template exists, otherwise false</returns>
public static boolean exist(RecId _recId)
{
    return _recId && (select firstonly RecId from NVOrderTemplate
                  where NVOrderTemplate.RecId == _recId).RecId != 0;
}
